head.script:

var com = {};

// 변경사항 1. com.initFrame 함수 수정 : onkeyup 대신 onbeforepaste 이벤트를 사용하도록 수정
com.initFrame = function($p) { 
    var tmpArr= com.getChildren(WebSquare.getBody(), {includePlugin : "inputCalendar gridView ", recursive:true});
    tmpArr.forEach(function(obj) {
         if(obj.getPluginName()=="inputCalendar"){
            obj.bind("onbeforepaste", function(data){
                return com.input_validation(obj, data);  // 처리된 data를  return하면 해당 값이 input에 세팅된다.
            });
        } else if(obj.getPluginName()=="gridView"){
            obj.bind("onbeforepaste", function(info) {
                var retData = com.gridInput_validation(info.data[0][0]);    // gridView에서의 붙여넣기는 하위호환을 위해 data가 이중 array로 감싸여 있다. 
                if (obj.editedCell) {  // 편집 모드인 경우
                    return retData;   // 마찬가지로 처리된 데이터를 리턴하면 해당 값이 input에 세팅된다. 
                } else {  // 편집 모드가 아닌 경우에 붙여넣기
                    obj.dataList.setCellData(info.rowIndex, info.colIndex, retData);   // 이 경우엔 dataList에 값을 세팅하고 return false를 하여 엔진 처리를 막는다.
                    return false;
                }
            });
        }  
    });
};

com.getChildren = function(comObj, options) {
	return WebSquare.util.getChildren(comObj, options);
};



/**
 * inputCalender 이벤트 validation
 * @param     $p      :  현재 frame ,obj inputCalendar
 */

// 변경사항 2. com.input_validation 함수를 com.gridInput_validation와 동일하게 구현 
com.input_validation = function(obj, pastedValue) {
	var value = pastedValue;

	//붙여넣기시 월1~9월 0 입력 추가
	//년월일 체크
	if(value.length > 8 && /[년|월|일]/.test(value)){
		var yearIndex = value.indexOf("년");
		var monthIndex = value.indexOf("월");
		var dayIndex = value.indexOf("일");
		var year = ""; 
		var month = "";
		var day = "";

		if(yearIndex == 4){
			year = value.substring(0,yearIndex);
		}
		if(monthIndex == 6 ){
			month = "0"+value.substring(yearIndex+1,monthIndex);
		}else if(monthIndex == 7 ){
			month = value.substring(yearIndex+1,monthIndex);
		}
		if(dayIndex == 8 ){
			day = "0"+value.substring(monthIndex+1,dayIndex);
		}else if(dayIndex == 9 ){
			if(monthIndex == 7){
				day ="0" +value.substring(monthIndex+1,dayIndex);
			}else{
				day =value.substring(monthIndex+1,dayIndex); 
			}
		}else if (dayIndex == 10){
			day = value.substring(monthIndex+1,dayIndex);
		}

		value = year+month+day;
	}
	//yyyy-mm-dd 브라우저 저장형식
	if(value.length > 8 && /^\d{4}-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01]])/.test(value)){
		var year = value.substring(0,4); 
		var month = value.substring(5,7);
		var day = value.substring(8,10);

		value = year+month+day;
	}

    var rtn=com.fn_RegTest(value);

    if(rtn==false)
    {
    	value = value.substring(0,value.length-1);
    }
    return value;

};

/**
 * Grid Calender 이벤트 validation
 * @param     obj:  그리드 ,eventInfo :{
						    "rowIndex": 2,
						    "colIndex": 4,
						    "colID": "stngRgstYmd",
						    "oldValue": "ㅇ1",
						    "newValue": "ㅇ12",
						    "inputType": "calendar",
						    "keyCode": 50
						}
 */
com.gridInput_validation = function(elValue) {
	var value=elValue;
	//붙여넣기시 월1~9월 0 입력 추가
	//년월일 체크
	if(value.length > 8 && /[년|월|일]/.test(value)){
		var yearIndex = value.indexOf("년");
		var monthIndex = value.indexOf("월");
		var dayIndex = value.indexOf("일");
		var year = ""; 
		var month = "";
		var day = "";

		if(yearIndex == 4){
			year = value.substring(0,yearIndex);
		}
		if(monthIndex == 6 ){
			month = "0"+value.substring(yearIndex+1,monthIndex);
		}else if(monthIndex == 7 ){
			month = value.substring(yearIndex+1,monthIndex);
		}
		if(dayIndex == 8 ){
			day = "0"+value.substring(monthIndex+1,dayIndex);
		}else if(dayIndex == 9 ){
			if(monthIndex == 7){
				day ="0" +value.substring(monthIndex+1,dayIndex);
			}else{
				day =value.substring(monthIndex+1,dayIndex);
			}
		}else if (dayIndex == 10){
			day = value.substring(monthIndex+1,dayIndex);
		}

		value = year+month+day;
	}

	//yyyy-mm-dd 브라우저 저장형식
	if(value.length > 8 && /^\d{4}-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01]])/.test(value)){
		var year = value.substring(0,4); 
		var month = value.substring(5,7);
		var day = value.substring(8,10);

		value = year+month+day;
	}

	var rtn=com.fn_RegTest(value);

	if(rtn==false)
	{
		value = value.substring(0,value.length-1);
	}

	return value;
};


/**
 * 년월일 정규식 체크
 */
com.fn_RegTest = function(value) {
    var dateRegex="";
    var testValuze="";


    if(value.length==5){
        dateRegex = /^[01]$/;
        testValue=value.substring(value.length - 1);
    } else if(value.length==6){
        dateRegex = /^(0[1-9]|1[0-2])$/;
        testValue=value.substring(4, 6)
    } else if(value.length==7){
        dateRegex = /^[0-3]$/;
        testValue=value.substring(6, 7)
    } else if(value.length==8){
        dateRegex = /^(0[1-9]|[12][0-9]|3[01])$/;
        testValue=value.substring(6, 8)
    } else if (value.length > 8){
    	dateRegex = /^(0[1-9]|[12][0-9]|3[01])$/;
    	testValue=value.replace(/[^0-9]/gi,"");

    }


    if (value.length > 4 && !dateRegex.test(testValue)) {
        return false;
    } else {
        return true;
    }
};

        /**
        * 2019-08-06 11:12 처럼 포맷된 형태의 값을 복사붙여넣기 시 inputCalendar onviewchange 이벤트 발생안함.
        * 201908061122 처럼 포맷되지 않은 데이터를 붙여넣기한 직후에는 위 값을 붙여넣어도 onviewchange 발생함.
        */
        /**
        * IE에서 탭으로 이동 시 포맷값 유지됨.
        * dataDragSelect=true 이면 IE에서 셀 클릭 시 포맷값 유지됨.
        */
	scwin.onpageload = function() {

		com.initFrame($p);
		dataMap1.setJSON({"key1":"20240101"});  //2019-12-30 09:10
	};




	scwin.inputCalendar1_onviewchange = function(info) {
