	};

	scwin.gridView1_oncellindexchange = function(row,col,oldRow,oldCol) {
        console.log("gridView1_oncellindexchange: ",row,col,oldRow,oldCol);
		var colID = gridView1.getColumnID(col);
        if(colID == "col1") {
            gridView1.setFocusedCell(row, col, false);
        }
	};
